package main
import("encoding/json";"math";"os";"testing";"path/filepath";_ "embed")
//go:embed testdata/algorithm-graphs.json
var primary_graphs_data []byte
const test_w=2*math.Pi*4124/(1<<20)
func TestAnalyticHarmonics(t *testing.T){
 rows:=[]map[string]interface{}{};max_error,max_hold:=0.,0.
 for _,amplitude:=range []float64{512,8170}{for _,phase:=range []float64{0,.37,2.1,6.281}{for _,age:=range []float64{-.5,.5}{for _,q:=range []float64{1,2,16}{for _,dc:=range []float64{-8,73}{
  v,truth:=analytic_wave(amplitude,phase+age*test_w,dc,q);fit,e:=project(v,8192,16384,64,test_w);if e!=nil{t.Fatal(e)};err:=0.;for i,h:=range fit.Terms{err=math.Max(err,math.Abs(h.Sin-truth.Terms[i].Sin));err=math.Max(err,math.Abs(h.Cos-truth.Terms[i].Cos))};hold:=prediction_rms(v,1024,5120,fit,test_w,0);max_error=math.Max(max_error,err);max_hold=math.Max(max_hold,hold);if err>1||hold>q{t.Fatalf("finite coefficient/holdout guard amp%g phase%g age%g Q%g:err%g hold%g",amplitude,phase,age,q,err,hold)};rows=append(rows,map[string]interface{}{"amplitude":amplitude,"phase":phase,"native_latch_age":age,"quantum":q,"dc":dc,"maximum_coefficient_error_pcm":err,"own_holdout_rms_pcm":hold,"training_residual_pcm":fit.Residual})
 }}}}}
 write_evidence(t,"synthetic-harmonics.json",map[string]interface{}{"records":len(rows),"fixed_harmonics":64,"coefficient_guard_pcm":1,"holdout_guard_pcm":"one quantization quantum","maximum_coefficient_error_pcm":max_error,"maximum_holdout_rms_pcm":max_hold,"observations":rows,"scope":"Finite independent analytic signals; not chip accuracy or physical pass bands"});t.Logf("%d analytic fixtures,max coefficient%gPCM,max holdout%gPCM",len(rows),max_error,max_hold)
}
func analytic_wave(amplitude,phase,dc,q float64)([]float64,projection){
 r:=projection{DC:dc,Terms:make([]harmonic,64)};for h:=1;h<=64;h++{a,b:=0.,0.;switch h{case 1:a=.8;case 2:b=.3;case 3:a=.2;case 7:b=.07;case 17:a=.05;case 63:b=.01};s,c:=math.Sincos(float64(h)*phase);a,b=amplitude*(a*c-b*s),amplitude*(b*c+a*s);r.Terms[h-1]=harmonic{h,a,b,.5*(a*a+b*b)}};v:=make([]float64,16384);for n:=range v{x:=predict(r,test_w*float64(n));if q>0{x=q*math.RoundToEven(x/q)};v[n]=x};return v,r
}
func TestNonlinearBesselMath(t *testing.T){
 rows:=[]map[string]interface{}{}
 for _,beta:=range []float64{.1,.5,2,4}{for _,phase:=range []float64{0,.61,6.281}{v:=make([]float64,16384);for n:=range v{theta:=test_w*float64(n)+phase;v[n]=math.RoundToEven(-8+1024*math.Sin(theta+beta*math.Sin(theta)))};p,e:=project(v,8192,16384,64,test_w);if e!=nil{t.Fatal(e)};err:=0.;for _,h:=range p.Terms{a:=1024*(math.Jn(h.Order-1,beta)-math.Jn(-h.Order-1,beta));s,c:=math.Sincos(float64(h.Order)*phase);err=math.Max(err,math.Abs(h.Sin-a*c));err=math.Max(err,math.Abs(h.Cos-a*s))};hold:=prediction_rms(v,1024,5120,p,test_w,0);if err>.25||hold>.6{t.Fatal("Bessel forward math",beta,phase,err,hold)};rows=append(rows,map[string]interface{}{"beta":beta,"phase":phase,"maximum_coefficient_error_pcm":err,"own_holdout_rms_pcm":hold})}}
 write_evidence(t,"synthetic-bessel.json",map[string]interface{}{"records":len(rows),"source":"Independent analytic sin(theta+beta*sin(theta)) vs math.Jn expansion,not a chip scaling/recurrence","observations":rows})
}
func TestOneSharedOriginAndHoldout(t *testing.T){
 rows:=[]map[string]interface{}{}
 for _,amplitude:=range []float64{512,2048,8170}{for _,phase:=range []float64{.001,.37,2.1,6.282}{model,_:=analytic_wave(amplitude,0,-8,16);v,_:=analytic_wave(amplitude,phase,-8,16);a,e:=project(v,8192,16384,64,test_w);if e!=nil{t.Fatal(e)};b,e:=project(model,8192,16384,64,test_w);if e!=nil{t.Fatal(e)};m:=align(a,b);if m.Phase==nil{t.Fatal("missing phase")};delta:=math.Remainder(*m.Phase-phase,2*math.Pi);hold:=prediction_rms(v,1024,5120,b,test_w,*m.Phase);if math.Abs(delta)>.0005||m.CoefficientRMS>2||hold>17{t.Fatalf("shared origin phase%g measured%g coeff%g hold%g",phase,*m.Phase,m.CoefficientRMS,hold)};rows=append(rows,map[string]interface{}{"amplitude":amplitude,"true_phase":phase,"measured_phase":*m.Phase,"phase_error":delta,"coefficient_rms_pcm":m.CoefficientRMS,"holdout_rms_pcm":hold})}}
 base,truth_base:=analytic_wave(2048,0,-8,16);ref,e:=project(base,8192,16384,64,test_w);if e!=nil{t.Fatal(e)};failures:=map[string]map[string]float64{}
 for _,name:=range []string{"gain","relative_harmonic_phase","pre_event_phase_jump","dc_change"}{v:=append([]float64(nil),base...);for n:=range v{switch name{case "gain":v[n]=math.RoundToEven(-8+1.05*(v[n]+8));case "relative_harmonic_phase":v[n]+=math.RoundToEven(400*(math.Sin(3*test_w*float64(n)+.2)-math.Sin(3*test_w*float64(n))));case "pre_event_phase_jump":if n<6000{theta:=test_w*float64(n)+.2;v[n]=math.RoundToEven(predict(truth_base,theta))};case "dc_change":v[n]+=10}};a,e:=project(v,8192,16384,64,test_w);if e!=nil{t.Fatal(e)};m:=align(a,ref);if m.Phase==nil{t.Fatal(name)};hold:=prediction_rms(v,1024,5120,ref,test_w,*m.Phase);if name=="pre_event_phase_jump"{if hold<50{t.Fatal("late fit concealed earlier phase jump",hold)}}else if m.CoefficientRMS<=2{t.Fatal("free gain/phase/DC concealed",name,m)};failures[name]=map[string]float64{"coefficient_rms_pcm":m.CoefficientRMS,"holdout_rms_pcm":hold}}
 write_evidence(t,"synthetic-one-origin.json",map[string]interface{}{"positive_records":len(rows),"fixed_pair_coefficient_screen_pcm":2,"positive":rows,"above_floor_rejected_controls":failures,"scope":"Finite math qualification only; no physical pair band inferred"})
}
func TestUnobservableAndNonperiodic(t *testing.T){
 quiet:=make([]float64,16384);p,e:=project(quiet,8192,16384,64,test_w);if e!=nil||p.State!="quiet_exact_zero"{t.Fatal(p,e)};m:=align(p,p);if m.Phase!=nil||m.EquivalentMinima!=0{t.Fatal("quiet got a phase",m)}
 even:=make([]float64,16384);for n:=range even{even[n]=1000*math.Sin(2*test_w*float64(n))};a,e:=project(even,8192,16384,64,test_w);if e!=nil{t.Fatal(e)};m=align(a,a);if m.EquivalentMinima<2{t.Fatal("half-cycle equivalent origins hidden",m)}
 rows:=[]map[string]interface{}{};for _,name:=range []string{"subharmonic","drifting_gain","irregular","generic1024phase"}{v:=make([]float64,16384);for n:=range v{theta:=test_w*float64(n);switch name{case "subharmonic":v[n]=1000*math.Sin(theta/2);case "drifting_gain":v[n]=(500+float64(n)/16)*math.Sin(theta);case "irregular":v[n]=1000*math.Sin(theta+.2*math.Sin(float64(n)*.0013));case "generic1024phase":angle:=2*math.Pi/1024*math.Floor(theta/(2*math.Pi/1024));v[n]=math.RoundToEven(8170*math.Sin(angle)-8)}};p,e:=project(v,8192,16384,64,test_w);if e!=nil{t.Fatal(e)};hold:=prediction_rms(v,1024,5120,p,test_w,0);if name!="generic1024phase"&&hold<50{t.Fatal("irregular signal forced periodic",name,hold)};rows=append(rows,map[string]interface{}{"control":name,"state":p.State,"training_residual_pcm":p.Residual,"own_holdout_rms_pcm":hold,"interpretation":"reported residual/holdout,not forced-period pass"})}
 write_evidence(t,"synthetic-unresolved.json",map[string]interface{}{"quiet_phase":nil,"even_harmonic_equivalent_phase_origins":m.EquivalentMinima,"controls":rows})
}
func write_evidence(t *testing.T,name string,value interface{}){t.Helper();b,e:=json.MarshalIndent(value,"","  ");if e!=nil{t.Fatal(e)};dir:=os.Getenv("JT143_ALGORITHM_QUALIFICATION_DIR");if dir==""{dir=t.TempDir()};f,e:=os.OpenFile(filepath.Join(dir,name),os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil{t.Fatal(e)};_,e=f.Write(append(b,'\n'));close_error:=f.Close();if e!=nil{t.Fatal(e)};if close_error!=nil{t.Fatal(close_error)}}
func TestPrimaryGraphToyMeasurementLimits(t *testing.T){
 type graph struct{Algorithm int `json:"algorithm"`;Edges [][]string `json:"edges"`;Outputs []string `json:"outputs"`};var primary struct{Graphs []graph `json:"graphs"`};e:=json.Unmarshal(primary_graphs_data,&primary);if e!=nil{t.Fatal(e)}
 toy:=func(g graph,tagged bool)[]float64{levels:=map[string]float64{"M1":32,"C1":40,"M2":48,"C2":24};v:=make([]float64,16384);for n:=range v{values:=map[string]float64{};theta:=test_w*float64(n);for _,op:=range []string{"M1","C1","M2","C2"}{tl:=levels[op];if !tagged{tl=32};input:=0.;for _,edge:=range g.Edges{if edge[1]==op{input+=values[edge[0]]}};values[op]=math.Pow(10,-.75*tl/20)*math.Sin(theta+12*input)};sum:=0.;for _,op:=range g.Outputs{sum+=values[op]};v[n]=-8+8170*sum};return v}
 fits:=[]projection{};for _,g:=range primary.Graphs{p,e:=project(toy(g,true),8192,16384,64,test_w);if e!=nil{t.Fatal(e)};fits=append(fits,p)};pairs:=[]map[string]interface{}{};minimum:=math.Inf(1)
 for a:=0;a<8;a++{for b:=a+1;b<8;b++{m:=align(fits[a],fits[b]);minimum=math.Min(minimum,m.CoefficientRMS);pairs=append(pairs,map[string]interface{}{"algorithms":[]int{a,b},"one_phase_coefficient_rms_pcm":m.CoefficientRMS,"equivalent_origins":m.EquivalentMinima})}}
 equal2,e:=project(toy(primary.Graphs[2],false),8192,16384,64,test_w);if e!=nil{t.Fatal(e)};equal3,e:=project(toy(primary.Graphs[3],false),8192,16384,64,test_w);if e!=nil{t.Fatal(e)};ambiguous:=align(equal2,equal3);if ambiguous.CoefficientRMS>1e-7{t.Fatal("equal-operator toy degeneracy hidden",ambiguous)}
 write_evidence(t,"synthetic-primary-toy.json",map[string]interface{}{"tagged_graphs":8,"tagged_pairs":pairs,"minimum_tagged_pair_difference_pcm":minimum,"equal_operator_alg2_alg3_rms_pcm":ambiguous.CoefficientRMS,"scope":"PRIMARY graph continuous math with arbitrary12rad/unit gain; NOT YM2151scaling,feedback recurrence,rounding,delay,or bit-accurate oracle; no feedback code copied"})
}
func TestIndependentLowLevelToneFrequency(t *testing.T){
 rows:=[]map[string]interface{}{};qualified,limited:=0,0
 for _,amp:=range []float64{128,258,515,1028,8170}{for _,phase:=range []float64{0,.3,1.2,2.4}{for _,q:=range []float64{1,2,16}{v:=make([]float64,16384);for n:=range v{v[n]=-8+q*math.RoundToEven(amp*math.Sin(test_w*float64(n)+phase)/q)};r:=estimate_tone(v,1024,16384);if r.Increment!=nil{qualified++;if math.Abs(*r.Increment-4124)>.1{t.Fatal("incorrect independent lowlevel frequency",amp,phase,q,r)}}else{limited++;if !(amp==128&&q==16){t.Fatal("unexpected unresolved tone",amp,phase,q,r)}};rows=append(rows,map[string]interface{}{"amplitude":amp,"phase":phase,"quantum":q,"measurement":r})}}}
 wrong:=make([]float64,16384);for n:=range wrong{wrong[n]=math.RoundToEven(-8+515*math.Sin(2*math.Pi*3900/(1<<20)*float64(n)))};r:=estimate_tone(wrong,1024,16384);if r.Increment==nil||math.Abs(*r.Increment-3900)>.1{t.Fatal("expected increment imposed on actual frequency",r)};write_evidence(t,"synthetic-lowlevel-tone.json",map[string]interface{}{"records":len(rows),"qualified":qualified,"resolution_limited":limited,"wrong3900_measured":r,"finite_frequency_guard_20bit_units":.1,"observations":rows})
}
